  kademe: 0,
  zorluk: 2,
  soru: "**Aşağıdaki cümlelerin hangisinde ek yanlışlığı vardır?**",
  gorsel: null,
  secenekler: ["Kardeşim yarınki sınava hazırlanıyor.", "Dedem bana eski günleri anlattı.", "Babam bizi gezi için okula bıraktı.", "Ablam beni hafta sonu denizi götürdü."],
  dogru: 3,
